 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==621){show();return;}if(request!=620)return;discoveryOpen=false;if(result==RESULT_OK&&data!=null)try{select(new JSONObject(data.getStringExtra("race")));}catch(Exception e){error(e);}else if(result==RESULT_FIRST_USER){stage="manual";draft.putString("name","");draft.putString("city","");draft.remove("km");draft.putBoolean("manualDateSet",false);show();}else{stage="goal";show();}}
 protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putBoolean("aiPlanning",aiPlanning);out.putString("aiRaw",aiRaw);out.putString("aiRevision",aiRevision);out.putString("previewFingerprint",fingerprint);out.putBoolean("discoveryOpen",discoveryOpen);out.putString("stage",stage);out.putBoolean("isRaceDraft",isRaceDraft);out.putString("goalKind",goalKind);out.putBundle("draft",draft);out.putString("race",raceDate.toString());out.putString("from",from.toString());out.putString("to",to.toString());out.putInt("longDay",longDay.getValue());out.putIntArray("days",days.stream().mapToInt(DayOfWeek::getValue).toArray());if(selected!=null)out.putString("selected",selected.toString());}
